/* Enter with bv->bv_len = sizeof buffer, returns with
 * actual length of string
 */
void slap_timestamp( time_t *tm, struct berval *bv )
{
	struct tm ltm;

	ldap_pvt_gmtime( tm, &ltm );

	bv->bv_len = lutil_gentime( bv->bv_val, bv->bv_len, &ltm );
}

