	dels = op->o_tmpalloc( sizeof(struct berval *) * no, op->o_tmpmemctx );

	if ( old->a_vals != old->a_nvals ) {
	while ( old ) {
		Modifications *mod;

		/* Skip contextCSN we screen ourselves */
		if ( is_ctx && old->a_desc == slap_schema.si_ad_contextCSN ) {
			old = old->a_next;
