								Debug( LDAP_DEBUG_SYNC,
									"dn_callback : new entry is older than ours "
									"%s ours %s, new %s\n",
									rs->sr_entry->e_name.bv_val,
									old->a_vals[0].bv_val,
									new->a_vals[0].bv_val );
								return LDAP_SUCCESS;
							} else if ( rc == 0 ) {
								Debug( LDAP_DEBUG_SYNC,
									"dn_callback : entries have identical CSN "
									"%s %s\n",
									rs->sr_entry->e_name.bv_val,
									old->a_vals[0].bv_val );
								return LDAP_SUCCESS;
							}
							memcpy( dni->oldcsn, old->a_nvals[0].bv_val,
									old->a_nvals[0].bv_len+1 );
